// ===============================================================================
// DAEMIND SRE - PARSER CANÔNICO DA SHOPEE (ORDER_SN, ESCROW, ITEM_LIST)
// ===============================================================================
const crypto = require('crypto');
const body = $json.body || $json;

const orderSn = body.order_sn || body.data?.order_sn || Date.now().toString();
const buyerUser = body.buyer_user || body.data?.buyer_user || {};
let rawPhone = (buyerUser.phone || body.recipient_address?.phone || '').toString().replace(/\D/g, '');
if (rawPhone.length >= 10 && rawPhone.length <= 11) {
  rawPhone = '55' + rawPhone;
}

const clienteNome = (buyerUser.user_name || body.recipient_address?.name || 'Cliente Shopee').trim();
const clienteEmail = (buyerUser.email || '').trim().toLowerCase();

const numeroPedido = parseInt(orderSn.replace(/\D/g, '') || Date.now(), 10);
const valorTotal = parseFloat(body.total_amount || body.data?.total_amount || 0);
const escrowLiquido = parseFloat(body.escrow_amount || body.data?.escrow_amount || valorTotal);
const orderStatus = (body.order_status || body.data?.order_status || '').toUpperCase();

let statusOperacional = 'Pendente';
if (['READY_TO_SHIP', 'PROCESSED', 'COMPLETED'].includes(orderStatus)) {
  statusOperacional = 'Pago';
} else if (['SHIPPED'].includes(orderStatus)) {
  statusOperacional = 'Enviado';
} else if (['CANCELLED', 'IN_CANCEL'].includes(orderStatus)) {
  statusOperacional = 'Cancelado';
}

const itemList = (body.item_list || body.data?.item_list || []).map(i => ({
  produto_nome: i.item_name || 'Produto Shopee',
  sku: i.item_sku || i.model_sku || 'SHOPEE_SKU',
  quantidade: parseInt(i.model_quantity_purchased || 1, 10),
  preco_unitario: parseFloat(i.model_discounted_price || 0)
}));

const dedupHash = crypto.createHash('sha256').update(`shopee_${orderSn}_${statusOperacional}_${valorTotal}`).digest('hex');

return [{
  json: {
    dedup_hash: dedupHash,
    order_sn: orderSn,
    numero_pedido: numeroPedido,
    cliente_nome: clienteNome,
    cliente_email: clienteEmail,
    cliente_whatsapp: rawPhone,
    valor_total: valorTotal,
    escrow_liquido: escrowLiquido,
    status_operacional: statusOperacional,
    item_list: itemList
  }
}];
